using Microsoft.Extensions.AI;

public class MinimalReActAgent
{
    private readonly IChatClient _client;
    private readonly List<AIFunction> _tools;
    private const int MaxIterations = 5;

    public MinimalReActAgent(IChatClient client, List<AIFunction> tools)
    {
        _client = client;
        _tools = tools;
    }

    public async Task<string> RunAsync(string userGoal, CancellationToken ct = default)
    {
        var conversation = new List<ChatMessage>
        {
            new(ChatRole.System, 
                "You are an autonomous problem-solving agent. When solving a problem, use the provided tools. " +
                "Always reflect on tool observations before deciding the next step."),
            new(ChatRole.User, userGoal)
        };

        var options = new ChatOptions { Tools = _tools, Temperature = 0.1f };

        for (int i = 0; i < MaxIterations; i++)
        {
            ChatCompletion completion = await _client.CompleteAsync(conversation, options, ct);
            conversation.Add(completion.Message);

            var functionCalls = completion.Message.Contents.OfType<FunctionCallContent>().ToList();

            // If model made no tool calls, it has reached its final answer
            if (functionCalls.Count == 0)
            {
                return completion.Message.Text ?? "Goal accomplished.";
            }

            // Execute all requested tool calls and feed observations back
            foreach (var call in functionCalls)
            {
                var tool = _tools.FirstOrDefault(t => t.Metadata.Name == call.Name)
                    ?? throw new InvalidOperationException($"Tool {call.Name} not found.");

                var toolResult = await tool.InvokeAsync(call.Arguments, ct);

                conversation.Add(new ChatMessage(ChatRole.Tool, toolResult?.ToString() ?? "null")
                {
                    Contents = { new FunctionResultContent(call.CallId, toolResult) }
                });
            }
        }

        return "Task paused: Reached maximum allowed reasoning iterations.";
    }
}
